"use client";

import "../../styles/teum-base.css";
import "../../styles/components/radio-group.css";
import { Radio } from "@base-ui/react/radio";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { useId } from "react";
import { cn } from "../../lib/cn";

export type RadioOption = {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
};

export type RadioGroupProps = Omit<RadioGroupPrimitive.Props<string>, "children"> & {
  label: string;
  description?: string;
  error?: string;
  options: readonly RadioOption[];
  orientation?: "vertical" | "horizontal";
};

export function RadioGroup({ className, label, description, error, options, orientation = "vertical", ...props }: RadioGroupProps) {
  const id = useId();
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;

  return (
    <div className="teum-radio-field" data-invalid={Boolean(error) || undefined}>
      <div id={id} className="teum-radio-field__label">{label}</div>
      {description && <div id={descriptionId} className="teum-field__description">{description}</div>}
      <RadioGroupPrimitive
        aria-labelledby={id}
        aria-describedby={[descriptionId, errorId].filter(Boolean).join(" ") || undefined}
        aria-invalid={Boolean(error) || undefined}
        className={cn("teum-radio-group", `teum-radio-group--${orientation}`, className)}
        {...props}
      >
        {options.map((option) => (
          <label className="teum-radio-option" key={option.value} data-disabled={option.disabled || undefined}>
            <Radio.Root value={option.value} disabled={option.disabled} className="teum-radio">
              <Radio.Indicator className="teum-radio__indicator" />
            </Radio.Root>
            <span><strong>{option.label}</strong>{option.description && <small>{option.description}</small>}</span>
          </label>
        ))}
      </RadioGroupPrimitive>
      {error && <div id={errorId} className="teum-field__error">{error}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-radio-field { display: grid; gap: 6px; min-width: 220px; }

.teum-radio-field__label { color: var(--teum-ink); font-size: var(--teum-type-label); font-weight: 540; }

.teum-radio-group { display: flex; gap: 4px; }

.teum-radio-option { display: flex; min-height: 32px; align-items: flex-start; gap: 9px; padding: 6px 0; color: var(--teum-ink); cursor: pointer; }

.teum-radio-option > span { display: grid; gap: 2px; line-height: 1.3; }

.teum-radio-option strong { font-size: var(--teum-type-ui); font-weight: 480; }

.teum-radio-option small { max-width: 280px; color: var(--teum-ink-tertiary); font-size: var(--teum-type-metadata); }

.teum-radio-option[data-disabled] { color: var(--teum-ink-disabled); cursor: not-allowed; }

.teum-radio {
  display: grid;
  width: 16px;
  height: 16px;
  margin-top: 1px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--teum-border-strong);
  border-radius: 50%;
  background: var(--teum-control-surface);
  cursor: inherit;
  transition: border-color var(--teum-hover-duration) ease, background-color var(--teum-hover-duration) ease, transform var(--teum-press-duration) var(--teum-ease-out, ease-out);
}

.teum-radio[data-checked] { border-color: var(--teum-inverse); background: var(--teum-inverse); }

.teum-radio__indicator { width: 6px; height: 6px; border-radius: 50%; background: var(--teum-on-inverse); }

.teum-radio:focus-visible { outline: 2px solid var(--teum-focus-control); outline-offset: 2px; }

.teum-radio[data-disabled] { border-color: var(--teum-border); background: var(--teum-gray-100); }

@media (hover: hover) and (pointer: fine) {
.teum-radio-option:hover .teum-radio:not([data-disabled]) { border-color: var(--teum-gray-700); }
}

.teum-field__description,
.teum-field__error { color: var(--teum-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.teum-field__error { color: var(--teum-fg-danger); font-weight: 520; }

:root[data-theme="dark"] .teum-radio[data-disabled] { background: rgb(255 255 255 / 0.025); color: var(--teum-ink-disabled); }

:root[data-theme="dark"] .teum-radio[data-checked] { box-shadow: none; }

.teum-radio__indicator {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--teum-ease-out), transform 140ms var(--teum-ease-out);
}

@starting-style {
.teum-radio__indicator {
    opacity: 0;
    transform: scale(.9);
  }
}

@media (prefers-reduced-motion: reduce) {
.teum-radio:active { transform: none; }

.teum-radio__indicator { transition-duration: 0.01ms; }
}
}
